import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // Plane dimensions (title area)
  const width = 4.0;
  const height = 1.5;
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: '#0b0b10',           // surface fallback until texture loads
  });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load the gradient/grain texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // "Collection" headline text
  const headline = ctx.fontAtlas.createText('Collection', {
    fontSize: 96,
    color: '#e8ecf2',          // paper
    align: 'center',
  });
  headline.position.set(0, 0, 0.01);   // centered, slightly forward
  group.add(headline);

  // Event handlers (none)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // No GSAP timelines to kill
  };

  return group;
}
